"""Create a local .env with fresh random secrets (used by setup.bat). Never overwrites."""
import secrets
import sys
from pathlib import Path

target = Path(__file__).resolve().parent.parent / ".env"
if target.exists():
    print(".env already exists - leaving it untouched.")
    sys.exit(0)
target.write_text(
    "# Generated by scripts/make_env.py - local development only. Do not commit.\n"
    "TRUSTVAULT_ENV=development\n"
    "DATABASE_URL=\n"
    f"TRUSTVAULT_MASTER_KEY={secrets.token_urlsafe(48)}\n"
    f"TRUSTVAULT_AUDIT_KEY={secrets.token_urlsafe(48)}\n"
    "TRUSTVAULT_DEMO_MODE=true\n"
    "TRUSTVAULT_SEED_DEMO=true\n",
    encoding="utf-8",
)
print("Created .env with new random secrets.")
